 "content": "from collections import Counter


def transform(grid):
    """Map the most frequent color to 0 and the less frequent one to that color."""
    counts = Counter(value for row in grid for value in row)
    if len(counts) != 2:
        raise ValueError("expected a two-color grid")
    dominant = max(counts, key=counts.get)
    return [[0 if value == dominant else dominant for value in row] for row in grid]
